1	import { finding } from '../../../engine/checks/helpers/findings.mjs';
2	// Namespace-imported and guarded for the same reason legacy-shape-in-use is: a
3	// member's pack lane and engine lane converge on separate cycles, and this pack
4	// can sit beside a task-contract that predates either export.
5	import * as contract from '../src/contract/task-contract.mjs';
6	import * as calendar from '../src/contract/calendar.mjs';
7	import * as declarationText from '../src/contract/task-declaration-text.mjs';
8	
9	// THE ADVISORY HALF OF THE TASK CONTRACT'S FIELD TOLERANCES. `normalizeTaskDeclaration`
10	// accepts two generations of field names, the retired one-word outcome ceilings,
11	// the retired `frequency` field (which reads as the cadence term it always meant,
12	// docs/PRINCIPLES.md) and a declaration stating no `trigger` (whose value is
13	// derived from the shape of its conditions), so a task declared in the oldest
14	// vocabulary runs exactly like one declared today — and nothing told its author that
15	// the acceptance ends a convergence window after this advisory ships (#1642, #1725).
16	//
17	// The trigger half is the odd one: what it reports is an ABSENCE, not a spelling, so
18	// there is no wrong line to point at — it points at the line the field goes ON, which
19	// is the anchor the nightly rewrite uses to put it there.
20	//
21	// It reads the declaration SOURCE rather than the normalized object, because by
22	// the time anything holds a task declaration the legacy spelling is gone: the
23	// door normalizes at load, which is what makes the tolerance invisible.
24	// Matching is therefore textual and deliberately conservative — a top-level key
25	// line in a task declaration — so the finding always points at a line an author
26	// can edit. The key is quoted and the value quote is whichever the file uses.
27	//
28	// ADVISORY: the old spelling works, and a task file is a member's own content.
29	const TASK_FILE = /(^|\/)tasks\/[^/]+\/task\.json$/;
30	const isTaskFile = (path) =>
31	  (typeof declarationText.isTaskDeclarationPath === 'function'
32	    ? declarationText.isTaskDeclarationPath(path)
33	    : TASK_FILE.test(path));
34	
35	const rule = {
36	  id: 'legacy-task-fields',
37	  severity: 'advisory',
38	  since: '2026-09-03',
39	  description: 'Task declarations name their fields and outcome in the current vocabulary',
40	  why: 'the contract accepts two retired generations of field names, two retired generations of outcome ceilings, the retired frequency field and an unstated trigger for one convergence window after this advisory ships (#1642, #1725) — nothing counts who is still on them, so a declaration not brought up to the vocabulary inside that window simply stops being read',
41	
42	  run(ctx) {
43	    const fields = contract.LEGACY_FIELDS ?? {};
44	    const outcomes = contract.LEGACY_OUTCOMES ?? {};
45	    const ceilings = contract.LEGACY_CEILINGS ?? {};
46	    const names = Object.keys(fields);
47	    if (names.length === 0 && Object.keys(outcomes).length === 0 && Object.keys(ceilings).length === 0) return [];
48	
49	    const fieldRe = names.length ? new RegExp(`^\\s*"?(${names.join('|')})"?\\s*:`) : null;
50	    const outcomeRe = /^\s*"?expected_outcome"?\s*:\s*['"]([^'"]+)['"]/;
51	    // The cadence field, retired into the expression. Guarded on the engine
52	    // exporting the term spelling: beside an older calendar the field is not a
53	    // tolerance yet, and reporting it would ask for an edit that engine rejects.
54	    const frequencyRe = typeof calendar.cadenceTermFor === 'function' ? /^\s*"?frequency"?\s*:\s*['"]([^'"]+)['"]/ : null;
55	
56	    // Guarded on the engine carrying the field at all: beside an older contract a
57	    // declaration stating no trigger is not on a tolerance yet, and asking for the
58	    // key would ask for one that engine's own schema rejects.
59	    const triggers = Array.isArray(contract.TRIGGERS) ? contract.TRIGGERS : null;
60	    const statedTrigger = /^\s*"?trigger"?\s*:/;
61	    // Where the field goes, in the order the rewrite tries them: with the conditions
62	    // it reads as one sentence, else before the outcome the contract requires.
63	    const triggerAnchors = [/^\s*"?preconditions"?\s*:/, /^\s*"?expected_outcome"?\s*:/];
64	
65	    const out = [];
66	    for (const file of ctx.files.filter(isTaskFile)) {
67	      const text = ctx.read(file);
68	      if (text === null) continue;
69	      const lines = text.split('\n');
70	      if (triggers && !lines.some((l) => statedTrigger.test(l))) {
71	        const anchor = triggerAnchors.map((re) => lines.findIndex((l) => re.test(l))).find((i) => i !== -1);
72	        // Only where there is a line to point at: a declaration with neither anchor
73	        // is malformed, and the shape check is what says so.
74	        if (anchor !== undefined) {
75	          // The value the door would derive, so the fix is the edit and not a choice.
76	          const conditions = /"?preconditions"?\s*:\s*\[([^\]]*)\]/.exec(text)?.[1] ?? '';
77	          const implied = conditions.split(',').some((e) => e.replace(/['"]/g, '').split('||').some((alt) => alt.trim() !== ''))
78	            ? contract.TRIGGER_SCHEDULE : contract.TRIGGER_REQUEST;
79	          out.push(finding(rule, {
80	            file,
81	            line: anchor + 1,
82	            what: 'states no `trigger`, so whether the scheduler asks it is read off the shape of its conditions',
83	            fix: `state it — \`"trigger": "${implied}"\` is what those conditions are read as today, so writing it changes nothing except that the next reader can see it; the nightly update writes it into a member's own task files`,
84	          }));
85	        }
86	      }
87	      lines.forEach((text_line, i) => {
88	        const field = fieldRe?.exec(text_line);
89	        if (field) {
90	          out.push(finding(rule, {
91	            file,
92	            line: i + 1,
93	            what: `declares the retired field \`${field[1]}\``,
94	            fix: `rename it to \`${fields[field[1]]}\` — the contract maps every retired spelling straight to today's name, so this is a one-line edit with no behaviour change`,
95	          }));
96	        }
97	        const frequency = frequencyRe?.exec(text_line);
98	        if (frequency) {
99	          const term = (calendar.ACCEPTED_FREQUENCIES ?? []).includes(frequency[1]) ? calendar.cadenceTermFor(frequency[1]) : 'due:<daily|weekly|monthly>';
100	          const fix = term === null
101	            ? 'write `"trigger": "request"` and drop the field, and a `"none"` beside it: `"manual"` meant no schedule at all, which a declaration now says outright; the nightly update rewrites a member\'s own task files'
102	            : `write it as the first condition — \`"preconditions": ["${term}", …]\` — with \`"trigger": "schedule"\` beside it, and drop a \`"none"\`; the field reads as exactly that today, and the nightly update rewrites a member's own task files`;
103	          out.push(finding(rule, {
104	            file,
105	            line: i + 1,
106	            what: 'declares the retired field `frequency`',
107	            fix,
108	          }));
109	        }
110	        const outcome = outcomeRe.exec(text_line);
111	        if (outcome && Object.hasOwn(outcomes, outcome[1])) {
112	          out.push(finding(rule, {
113	            file,
114	            line: i + 1,
115	            what: `declares the retired outcome ceiling \`${outcome[1]}\``,
116	            fix: `write \`expected_outcome: 'fresh_pr'\` with \`automerge: '${outcomes[outcome[1]]}'\` beside it — the one word always meant that pair, and spelling it out is what lets the policy be narrowed later`,
117	          }));
118	        } else if (outcome && Object.hasOwn(ceilings, outcome[1])) {
119	          out.push(finding(rule, {
120	            file,
121	            line: i + 1,
122	            what: `declares the retired outcome ceiling \`${outcome[1]}\``,
123	            fix: `write \`expected_outcome: '${ceilings[outcome[1]]}'\` — the word it became, in the vocabulary that also says amend_existing_or_create_new_pr and supersede_existing_pr`,
124	          }));
125	        }
126	      });
127	    }
128	    return out;
129	  },
130	};
131	
132	export default rule;
