import { finding } from '../../../engine/checks/helpers/findings.mjs';
// Namespace-imported and guarded for the same reason legacy-shape-in-use is: a
// member's pack lane and engine lane converge on separate cycles, and this pack
// can sit beside a task-contract that predates either export.
import * as contract from '../src/contract/task-contract.mjs';
import * as calendar from '../src/contract/calendar.mjs';
import * as declarationText from '../src/contract/task-declaration-text.mjs';

// THE ADVISORY HALF OF THE TASK CONTRACT'S FIELD TOLERANCES. `normalizeTaskDeclaration`
// accepts two generations of field names, the retired one-word outcome ceilings,
// the retired `frequency` field (which reads as the cadence term it always meant,
// docs/PRINCIPLES.md) and a declaration stating no `trigger` (whose value is
// derived from the shape of its conditions), so a task declared in the oldest
// vocabulary runs exactly like one declared today — and nothing told its author that
// the acceptance ends a convergence window after this advisory ships (#1642, #1725).
//
// The trigger half is the odd one: what it reports is an ABSENCE, not a spelling, so
// there is no wrong line to point at — it points at the line the field goes ON, which
// is the anchor the nightly rewrite uses to put it there.
//
// It reads the declaration SOURCE rather than the normalized object, because by
// the time anything holds a task declaration the legacy spelling is gone: the
// door normalizes at load, which is what makes the tolerance invisible.
// Matching is therefore textual and deliberately conservative — a top-level key
// line in a task declaration — so the finding always points at a line an author
// can edit. The key is quoted and the value quote is whichever the file uses.
//
// ADVISORY: the old spelling works, and a task file is a member's own content.
const TASK_FILE = /(^|\/)tasks\/[^/]+\/task\.json$/;
const isTaskFile = (path) =>
  (typeof declarationText.isTaskDeclarationPath === 'function'
    ? declarationText.isTaskDeclarationPath(path)
    : TASK_FILE.test(path));

const rule = {
  id: 'legacy-task-fields',
  severity: 'advisory',
  since: '2026-09-03',
  description: 'Task declarations name their fields and outcome in the current vocabulary',
  why: 'the contract accepts two retired generations of field names, two retired generations of outcome ceilings, the retired frequency field and an unstated trigger for one convergence window after this advisory ships (#1642, #1725) — nothing counts who is still on them, so a declaration not brought up to the vocabulary inside that window simply stops being read',

  run(ctx) {
    const fields = contract.LEGACY_FIELDS ?? {};
    const outcomes = contract.LEGACY_OUTCOMES ?? {};
    const ceilings = contract.LEGACY_CEILINGS ?? {};
    const names = Object.keys(fields);
    if (names.length === 0 && Object.keys(outcomes).length === 0 && Object.keys(ceilings).length === 0) return [];

    const fieldRe = names.length ? new RegExp(`^\\s*"?(${names.join('|')})"?\\s*:`) : null;
    const outcomeRe = /^\s*"?expected_outcome"?\s*:\s*['"]([^'"]+)['"]/;
    // The cadence field, retired into the expression. Guarded on the engine
    // exporting the term spelling: beside an older calendar the field is not a
    // tolerance yet, and reporting it would ask for an edit that engine rejects.
    const frequencyRe = typeof calendar.cadenceTermFor === 'function' ? /^\s*"?frequency"?\s*:\s*['"]([^'"]+)['"]/ : null;

    // Guarded on the engine carrying the field at all: beside an older contract a
    // declaration stating no trigger is not on a tolerance yet, and asking for the
    // key would ask for one that engine's own schema rejects.
    const triggers = Array.isArray(contract.TRIGGERS) ? contract.TRIGGERS : null;
    const statedTrigger = /^\s*"?trigger"?\s*:/;
    // Where the field goes, in the order the rewrite tries them: with the conditions
    // it reads as one sentence, else before the outcome the contract requires.
    const triggerAnchors = [/^\s*"?preconditions"?\s*:/, /^\s*"?expected_outcome"?\s*:/];

    const out = [];
    for (const file of ctx.files.filter(isTaskFile)) {
      const text = ctx.read(file);
      if (text === null) continue;
      const lines = text.split('\n');
      if (triggers && !lines.some((l) => statedTrigger.test(l))) {
        const anchor = triggerAnchors.map((re) => lines.findIndex((l) => re.test(l))).find((i) => i !== -1);
        // Only where there is a line to point at: a declaration with neither anchor
        // is malformed, and the shape check is what says so.
        if (anchor !== undefined) {
          // The value the door would derive, so the fix is the edit and not a choice.
          const conditions = /"?preconditions"?\s*:\s*\[([^\]]*)\]/.exec(text)?.[1] ?? '';
          const implied = conditions.split(',').some((e) => e.replace(/['"]/g, '').split('||').some((alt) => alt.trim() !== ''))
            ? contract.TRIGGER_SCHEDULE : contract.TRIGGER_REQUEST;
          out.push(finding(rule, {
            file,
            line: anchor + 1,
            what: 'states no `trigger`, so whether the scheduler asks it is read off the shape of its conditions',
            fix: `state it — \`"trigger": "${implied}"\` is what those conditions are read as today, so writing it changes nothing except that the next reader can see it; the nightly update writes it into a member's own task files`,
          }));
        }
      }
      lines.forEach((text_line, i) => {
        const field = fieldRe?.exec(text_line);
        if (field) {
          out.push(finding(rule, {
            file,
            line: i + 1,
            what: `declares the retired field \`${field[1]}\``,
            fix: `rename it to \`${fields[field[1]]}\` — the contract maps every retired spelling straight to today's name, so this is a one-line edit with no behaviour change`,
          }));
        }
        const frequency = frequencyRe?.exec(text_line);
        if (frequency) {
          const term = (calendar.ACCEPTED_FREQUENCIES ?? []).includes(frequency[1]) ? calendar.cadenceTermFor(frequency[1]) : 'due:<daily|weekly|monthly>';
          const fix = term === null
            ? 'write `"trigger": "request"` and drop the field, and a `"none"` beside it: `"manual"` meant no schedule at all, which a declaration now says outright; the nightly update rewrites a member\'s own task files'
            : `write it as the first condition — \`"preconditions": ["${term}", …]\` — with \`"trigger": "schedule"\` beside it, and drop a \`"none"\`; the field reads as exactly that today, and the nightly update rewrites a member's own task files`;
          out.push(finding(rule, {
            file,
            line: i + 1,
            what: 'declares the retired field `frequency`',
            fix,
          }));
        }
        const outcome = outcomeRe.exec(text_line);
        if (outcome && Object.hasOwn(outcomes, outcome[1])) {
          out.push(finding(rule, {
            file,
            line: i + 1,
            what: `declares the retired outcome ceiling \`${outcome[1]}\``,
            fix: `write \`expected_outcome: 'fresh_pr'\` with \`automerge: '${outcomes[outcome[1]]}'\` beside it — the one word always meant that pair, and spelling it out is what lets the policy be narrowed later`,
          }));
        } else if (outcome && Object.hasOwn(ceilings, outcome[1])) {
          out.push(finding(rule, {
            file,
            line: i + 1,
            what: `declares the retired outcome ceiling \`${outcome[1]}\``,
            fix: `write \`expected_outcome: '${ceilings[outcome[1]]}'\` — the word it became, in the vocabulary that also says amend_existing_or_create_new_pr and supersede_existing_pr`,
          }));
        }
      });
    }
    return out;
  },
};

export default rule;

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://github.com/missingbulb/Claudinite/blob/main/packs/claudinite-tasks/task.schema.json",
  "title": "Claudinite task declaration",
  "description": "A tasks/<name>/task.json: what a task is, when it runs — its preconditions, cadence included — and what its run does to pull requests. The runtime contract is packs/claudinite-tasks/src/contract/task-contract.mjs; the enums here mirror its lists and a test holds them in step. Absent, automerge is nothing and agent_model is none; preconditions and the timeouts have no default.",
  "type": "object",
  "required": [
    "id",
    "description",
    "expected_outcome"
  ],
  "additionalProperties": false,
  "properties": {
    "$schema": {
      "type": "string"
    },
    "id": {
      "type": "string",
      "minLength": 1,
      "description": "The task's name — the same as its directory name."
    },
    "description": {
      "type": "string",
      "minLength": 1,
      "description": "What the task does, or why it exists, in at most fifty words — never what the other fields already say (the cadence, the conditions, the policy, the files)."
    },
    "frequency": {
      "type": "string",
      "enum": [
        "daily",
        "weekly",
        "monthly",
        "manual"
      ],
      "deprecated": true,
      "description": "The retired cadence field; read at the door as the first condition it always meant (`due:<cadence>`) with a `schedule` trigger, and `manual` as no condition at all with a `request` trigger. Write those two fields instead."
    },
    "trigger": {
      "type": "string",
      "enum": [
        "schedule",
        "request"
      ],
      "description": "Who mints an occurrence of this task. `schedule` is asked by the scheduler at every tick, and runs when its `preconditions` hold. `request` is asked by nobody: it runs only from an item somebody creates — a marked issue, a wake, a chain link, a fan-out target — at whose pick those same conditions are judged. A declaration stating no trigger is read off the shape of its `preconditions` for one convergence window (#1789)."
    },
    "preconditions": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "When the task runs: every listed condition must hold, `||` between alternatives. A cadence first where the task keeps one (`schedule:at-most-daily|at-most-weekly|at-most-monthly`, measured over whole UTC periods), `last-run-not-failed` to stop past the task's own failure park, then the built-in movement terms (e.g. \"substantive-change\", \"commits-under:<dir>\") or terms the task's own preconditions.mjs exports. The same conditions are judged whether the run was asked for by the scheduler or by a person, so this field never says WHETHER the task is on the schedule; `trigger` does. A scheduled task with no cadence term is asked at every tick and runs whenever its other conditions hold; a task with no conditions at all runs whenever an occurrence exists."
    },
    "expected_outcome": {
      "type": "string",
      "enum": [
        "no_code_changes",
        "fresh_pr",
        "amend_existing_or_create_new_pr",
        "supersede_existing_pr"
      ],
      "description": "What the run does to pull requests, resolved once by the executor and handed to both phases: `no_code_changes` opens none; `fresh_pr` opens one on a freshly minted branch and leaves the task's earlier pull requests alone; `amend_existing_or_create_new_pr` pushes onto the task's newest open pull request while it has no conflicts, a fresh branch otherwise; `supersede_existing_pr` takes a fresh branch and closes the task's earlier pull requests once its own exists (a green, unlanded one on an auto-merge repo is landed instead). The retired `none`/`pr` normalize to the first two."
    },
    "automerge": {
      "description": "What may land unreviewed, beside any expected_outcome that opens a pull request: \"nothing\", \"anything\", or a list of diff classes, each optionally reject:-prefixed and narrowable with `&&`. Optional: defaults to \"nothing\".",
      "oneOf": [
        {
          "type": "string",
          "enum": [
            "nothing",
            "anything"
          ]
        },
        {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      ]
    },
    "agent_model": {
      "type": "string",
      "enum": [
        "opus",
        "sonnet",
        "haiku",
        "none"
      ],
      "description": "The model family the agentic phase runs at; `none` runs no agent. Optional: defaults to `none`."
    },
    "agent_instructions": {
      "type": "string",
      "minLength": 1,
      "description": "The worker spec the agent session reads, a file beside this declaration (conventionally task.md). Required beside an agent_model other than none; no default."
    },
    "agent_execution_timeout": {
      "type": "integer",
      "minimum": 1,
      "description": "Seconds bounding the agentic run — generous; extreme protection, not a scheduling knob. Required beside an agent_model other than none: a running agent always has a bound."
    },
    "code_work": {
      "type": "string",
      "minLength": 1,
      "description": "The deterministic first phase: a command run with the task directory as cwd, e.g. \"node worker.mjs\". Task-local — no absolute path, no `..`. Optional: absent, there is no code work."
    },
    "code_work_timeout": {
      "type": "integer",
      "minimum": 1,
      "description": "Seconds after which the code_work subprocess is killed and the task fails. Required beside code_work: a subprocess always has a bound."
    },
    "schedule_after": {
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^[^/\\s]+/[^/\\s]+$"
      },
      "description": "Task ids (\"<pack>/<task>\") this task yields to while their items are live this cycle."
    },
    "on_interrupt": {
      "type": "string",
      "enum": [
        "requeue",
        "needs-human"
      ],
      "description": "What happens to the work item when a recovery path would re-execute it. Default `requeue`; `needs-human` for a genuinely one-shot side effect."
    },
    "invocation_endpoint": {
      "type": "string",
      "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$",
      "description": "A key in the repo's taskScheduler.agenticTaskInvocationEndpoints — never a URL — for a task needing reach an ordinary session in its repo does not have."
    },
    "code_work_required_secrets": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "The repo Actions secret names the code-work phase needs configured — the phase that runs Action-side, where a secret exists. Never GITHUB_* or CLAUDINITE_*."
    },
    "required_secrets": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "deprecated": true,
      "description": "The retired spelling of code_work_required_secrets; normalized at the door. Rename it."
    },
    "model_from_request": {
      "const": true,
      "description": "Reserved to the engine's built-in request task: run at the model the work item names."
    },
    "session_scope": {
      "type": "string",
      "enum": [
        "self",
        "fleet"
      ],
      "deprecated": true,
      "description": "Read by nothing since #974. Drop it; name an invocation_endpoint if the task needs wider reach."
    }
  }
}

