58	      if (text === null) continue;
59	      const flag = (what, fix) => out.push(finding(rule, { file, what, fix }));
60	      const advise = (what, fix) => out.push(finding(rule, { file, severity: 'advisory', what, fix }));
61	
62	      const decl = readDeclarationFields(text);
63	      if (decl.error) {
