76	      // in `preconditions`, and the door reads the field as exactly that term. ADVISORY
77	      // for the same reason as every rename below — the file keeps working, and the
78	      // nightly update rewrites a member's own — so what blocks is only a declaration
79	      // that states no "when" at all.
80	      const legacyFrequency = str('frequency');
81	      if (decl.has('frequency')) {
