131	        advise(`declares the legacy outcome ceiling "${outcome}"`,
132	          `write the pair it normalizes to: "expected_outcome": "fresh_pr", "automerge": "${LEGACY_OUTCOMES[outcome]}" — and consider a narrower policy than "${LEGACY_OUTCOMES[outcome]}" (a list of diff classes, e.g. ["comment-only-changes"])`);
133	      } else if (LEGACY_CEILINGS[outcome] !== undefined) {
134	        advise(`declares the legacy outcome ceiling "${outcome}"`,
135	          `write the word it became: "expected_outcome": "${LEGACY_CEILINGS[outcome]}" — the same behaviour, in the vocabulary that also offers amend_existing_or_create_new_pr and supersede_existing_pr`);
136	      } else if (!OUTCOMES.includes(outcome)) {
