    '  },',
    '};',
  ].join('\n');
  const files = (trigger) => ({
    [TASK]: json({ ...good, trigger, preconditions: ['about-this-issue'] }),
    '.claudinite/local/packs/mypack/tasks/growth-extract/preconditions.mjs': terms,
