const PACK = join(dirname(fileURLToPath(import.meta.url)), '../..');
const ENGINE = join(PACK, '..', '..', 'engine');
const SHELL = join(PACK, 'src/session/resolve-dispatch.mjs');

const OK = 0, USAGE = 2, NO_TRIGGER = 12, SCOPE_MISMATCH = 15;

const taskJson = (id) => `${JSON.stringify({
  id,
  frequency: 'daily',
  preconditions: ['none'],
  agent_model: 'sonnet',
  expected_outcome: 'fresh_pr',
  automerge: 'nothing',
  agent_instructions: 'task.md',
  agent_execution_timeout: 1800,
})}\n`;

// A scratch checkout shaped like the real thing: a declared pack carrying a
// well-formed task, plus an UNDECLARED pack carrying an equally well-formed one
// (so "pack not declared" is isolated from every other failure mode).
function fixtureRepo() {
=== loop 35-50
// `gate` is how a fixture states its verdict: the declarative expression is the
// only precondition mechanism, so a fixture that must decline (or throw) does it
// through a task-local term, exactly as a real task would.
const term = (holds) => new Map([['gate', { signals: [], holds }]]);
const RUNS = term(() => ({ holds: true }));
const task = (id, decl = {}, terms = RUNS) => ({
  pack: 'p', id, taskDir: process.cwd(), taskPath: `packs/p/tasks/${id}/task.md`,
  decl: normalizeTaskDeclaration({ id, frequency: 'daily', agent_model: 'sonnet', preconditions: ['gate'], expected_outcome: 'fresh_pr', ...decl }),
  terms,
});

// `random` is pinned ascending so a fixture with several pickable items picks the
// FIRST one it lists — production's draw is random (PRINCIPLES.md) and a test that let it
// vary would be a coin flip, not a test.
const ascendingDraw = () => { let n = 0; return () => (n += 1) / 1000; };

