  assert.equal(nextAnchor('monthly', '2026-01-31T10:00:00Z').toISOString(), '2026-02-01T00:00:00.000Z');
  assert.equal(mostRecentAnchor('manual', '2026-08-14T10:00:00Z'), null);
  assert.equal(periodMs('weekly'), 7 * 86400e3);
});

