// --- the schedule grid --------------------------------------------------------------------

// A row's cadence fields come from the roster's own reader rather than being typed
// here, so the fixture is what `buildRoster` would hand the board and not a copy that
// can drift from it.
const cadenced = (terms, declaration = {}) => ({ declaration: { preconditions: terms, ...declaration }, ...describeCadence(terms) });
const taskRow = (over = {}) => ({
  key: 'p/t', pack: 'p', task: 't', ...cadenced(['due:daily']),
  nextAsk: { kind: 'anchor', at: new Date(NOW + DAY) }, lastClosed: null, ...over,
});

test('a cell is read off the item that closed, parked or ran that day', () => {
  const axis = axisOf(NOW, SCHEDULE);
  const yesterday = iso(NOW - DAY);
  const grid = scheduleGrid([taskRow()], [
    item({ number: 1, state: 'closed', closed_at: yesterday, labels: labelled(OUTCOME_DONE) }),
=== model roster fixtures ===
  const [w] = warningsFor(item({ labels: [STATUS_BLOCKED], body, updated_at: stuck }), NOW, depsOpen);
  assert.match(w.text, /janitor/);
  assert.equal(warningsFor(item({ labels: [STATUS_BLOCKED], body }), NOW, depsOpen).length, 0, 'under the threshold is a normal wait');
  assert.equal(warningsFor(item({ labels: [STATUS_BLOCKED], body, updated_at: stuck }), NOW).length, 0,
    'a blocker outside the fetched window is unknown — absence is a state, not an alarm');
});

test('a park\'s severity follows its triage lane', () => {
  assert.equal(warningsFor(item({ labels: [NEEDS_HUMAN] }), NOW)[0].level, 'critical');
  const [w] = warningsFor(item({ labels: [NEEDS_HUMAN, STATUS_NEEDS_HUMAN_APPROVAL] }), NOW);
  assert.equal(w.level, 'warning');
  assert.match(w.text, /PR to approve/);
});

// --- the roster ----------------------------------------------------------------

const tasks = [
  { pack: 'basics', task: 'ci-performance', path: 'packs/basics/tasks/ci-performance/task.json', declaration: { preconditions: ['due:weekly'], agent_model: 'sonnet' } },
  { pack: 'claudinite-lifecycle', task: 'update', path: 'packs/claudinite-lifecycle/tasks/update/task.json', declaration: { preconditions: ['due:daily'] } },
];

test('every declared task gets a row, including one that has never run', () => {
  const rows = buildRoster({ tasks, items: [], now: NOW, schedule: SCHEDULE });
  assert.equal(rows.length, 2);
  assert.equal(rows.every((r) => r.current === null && r.history.length === 0), true);
  assert.ok(rows[0].nextAnchor instanceof Date);

