    const patched = stateTriggerText(`${JSON.stringify(decl, null, 2)}\n`);
    assert.equal(patched.trigger, statesConditions(preconditions) ? 'schedule' : 'request', JSON.stringify(preconditions));
    // …and what it writes is a declaration the contract now accepts, where before it
    // was one the contract would have read the same way by itself.
    assert.deepEqual(validateTaskDeclaration(parseTaskDeclaration(patched.text)), [], JSON.stringify(preconditions));
    derived += 1;
  }
  assert.equal(derived, shapes.length, 'every shape reached both assertions');
});

