  "$id": "https://github.com/missingbulb/Claudinite/blob/main/packs/claudinite-tasks/task.schema.json",
  "title": "Claudinite task declaration",
  "description": "A tasks/<name>/task.json: what a task is, when it runs — its preconditions, cadence included — and what its run does to pull requests. The runtime contract is packs/claudinite-tasks/src/contract/task-contract.mjs; the enums here mirror its lists and a test holds them in step. Absent, automerge is nothing and agent_model is none; preconditions and the timeouts have no default.",
  "type": "object",
  "required": [
    "id",
    "description",
    "trigger",
    "expected_outcome"
  ],
  "additionalProperties": false,
  "properties": {
    "$schema": {
      "type": "string"
    },
    "id": {
      "type": "string",
      "minLength": 1,
      "description": "The task's name — the same as its directory name."
    },
    "description": {
      "type": "string",
      "minLength": 1,
      "description": "What the task does, or why it exists, in at most fifty words — never what the other fields already say (the cadence, the conditions, the policy, the files)."
    },
    "frequency": {
      "type": "string",
      "enum": [
        "daily",
        "weekly",
        "monthly",
        "manual"
      ],
      "deprecated": true,
      "description": "The retired cadence field; read at the door as the first condition it always meant (`due:<cadence>`), and `manual` as no condition at all. Write the condition instead, with the `trigger` it belongs beside — which the door does not supply."
    },
    "trigger": {
      "type": "string",
      "enum": [
        "schedule",
        "request"
      ],
      "description": "Who mints an occurrence of this task. `schedule` is asked by the scheduler at every tick, and runs when its `preconditions` hold. `request` is asked by nobody: it runs only from an item somebody creates — a marked issue, a wake, a chain link, a fan-out target — at whose pick those same conditions are judged."
    },
    "preconditions": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "When the task runs: every listed condition must hold, `||` between alternatives. A cadence first where the task keeps one (`schedule:at-most-daily|at-most-weekly|at-most-monthly`, measured over whole UTC periods), `last-run-not-failed` to stop past the task's own failure park, then the built-in movement terms (e.g. \"substantive-change\", \"commits-under:<dir>\") or terms the task's own preconditions.mjs exports. The same conditions are judged whether the run was asked for by the scheduler or by a person, so this field never says WHETHER the task is on the schedule; `trigger` does. A scheduled task with no cadence term is asked at every tick and runs whenever its other conditions hold; a task with no conditions at all runs whenever an occurrence exists."
    },
    "expected_outcome": {
      "type": "string",
      "enum": [
        "no_code_changes",
        "fresh_pr",
        "amend_existing_or_create_new_pr",
        "supersede_existing_pr"
      ],
      "description": "What the run does to pull requests, resolved once by the executor and handed to both phases: `no_code_changes` opens none; `fresh_pr` opens one on a freshly minted branch and leaves the task's earlier pull requests alone; `amend_existing_or_create_new_pr` pushes onto the task's newest open pull request while it has no conflicts, a fresh branch otherwise; `supersede_existing_pr` takes a fresh branch and closes the task's earlier pull requests once its own exists (a green, unlanded one on an auto-merge repo is landed instead). The retired `none`/`pr` normalize to the first two."
    },
    "automerge": {
      "description": "What may land unreviewed, beside any expected_outcome that opens a pull request: \"nothing\", \"anything\", or a list of diff classes, each optionally reject:-prefixed and narrowable with `&&`. Optional: defaults to \"nothing\".",
      "oneOf": [
        {
          "type": "string",
          "enum": [
            "nothing",
            "anything"
          ]
        },
        {
          "type": "array",
          "minItems": 1,
          "items": {
            "type": "string",
            "minLength": 1
          }
        }
      ]
    },
    "agent_model": {
      "type": "string",
      "enum": [
        "opus",
        "sonnet",
        "haiku",
        "none"
      ],
      "description": "The model family the agentic phase runs at; `none` runs no agent. Optional: defaults to `none`."
    },
    "agent_instructions": {
      "type": "string",
      "minLength": 1,
      "description": "The worker spec the agent session reads, a file beside this declaration (conventionally task.md). Required beside an agent_model other than none; no default."
    },
    "agent_execution_timeout": {
      "type": "integer",
      "minimum": 1,
      "description": "Seconds bounding the agentic run — generous; extreme protection, not a scheduling knob. Required beside an agent_model other than none: a running agent always has a bound."
    },
    "code_work": {
      "type": "string",
      "minLength": 1,
      "description": "The deterministic first phase: a command run with the task directory as cwd, e.g. \"node worker.mjs\". Task-local — no absolute path, no `..`. Optional: absent, there is no code work."
    },
    "code_work_timeout": {
      "type": "integer",
      "minimum": 1,
      "description": "Seconds after which the code_work subprocess is killed and the task fails. Required beside code_work: a subprocess always has a bound."
    },
    "schedule_after": {
      "type": "array",
      "items": {
        "type": "string",
        "pattern": "^[^/\\s]+/[^/\\s]+$"
      },
      "description": "Task ids (\"<pack>/<task>\") this task yields to while their items are live this cycle."
    },
    "on_interrupt": {
      "type": "string",
      "enum": [
        "requeue",
        "needs-human"
      ],
      "description": "What happens to the work item when a recovery path would re-execute it. Default `requeue`; `needs-human` for a genuinely one-shot side effect."
    },
    "invocation_endpoint": {
      "type": "string",
      "pattern": "^[a-z0-9]+(-[a-z0-9]+)*$",
      "description": "A key in the repo's taskScheduler.agenticTaskInvocationEndpoints — never a URL — for a task needing reach an ordinary session in its repo does not have."
    },
    "code_work_required_secrets": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "description": "The repo Actions secret names the code-work phase needs configured — the phase that runs Action-side, where a secret exists. Never GITHUB_* or CLAUDINITE_*."
    },
    "required_secrets": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1
      },
      "deprecated": true,
      "description": "The retired spelling of code_work_required_secrets; normalized at the door. Rename it."
    },
    "model_from_request": {
      "const": true,
      "description": "Reserved to the engine's built-in request task: run at the model the work item names."
    },
    "session_scope": {
      "type": "string",
      "enum": [
        "self",
        "fleet"
      ],
      "deprecated": true,
      "description": "Read by nothing since #974. Drop it; name an invocation_endpoint if the task needs wider reach."
    }
  }
}

