39	  const section = body.slice(start);
40	  const named = [...section.matchAll(TERM_NAME)];
41	  return termsMap(Object.fromEntries(named.map((m, i) => {
42	    const block = section.slice(m.index, named[i + 1]?.index ?? section.length);
43	    return [m[1], { signals: [], needsItem: /\bneedsItem\s*:\s*true\b/.test(block) }];
44	  })));
